from pathlib import Path
import json,sys,signal
R=Path.cwd();sys.path.insert(0,str(R/'tools/experiments'));import m7_apple_package as p
O=Path(__file__).resolve().parent
if (O/'checks.json').exists():raise FileExistsError('Exclusive check receipt required')
paths=[R/'Cargo.toml',R/'Cargo.lock',*sorted((R/'src').rglob('*.rs')),R/'src/metal/kernels.metal',R/'src/metal/mlx.metal',*sorted((R/'tests').glob('*.rs')),*sorted((R/'tests/fixtures/mlx-affine-v1').glob('*')),R/'tools/reference/mlx_affine.py',R/'tools/reference/mlx_qwen.py',R/'tools/reference/tiny.py',Path(__file__).resolve(),Path(p.__file__).resolve()]
pins={str(f.relative_to(R)):p.sha(f) for f in paths};protected={'target/release/toklet':'5250694e814ea112148a52cfdeaf5bc6286ff2804b3acfd8f89e80bc73122a59','target/release/examples/cpu_bench':'e3debabbae7db9e5801bc9bfba177275444ebe1d9849eb3ad0f2dff487ac8dea'}
commands=[];primary=None;endpoints=[];previous=signal.signal(signal.SIGTERM,p.interrupted)
try:
 env,_=p.build_environment();env['CARGO_TARGET_DIR']=str(R/'artifacts/m8-rust-target')
 for n,h in protected.items():
  if p.sha(R/n)!=h:raise ValueError('Protected baseline differs before checks')
 fixture=json.loads((R/'tests/fixtures/mlx-affine-v1/manifest.json').read_text())
 if fixture['exporter_sha256']!=pins['tools/reference/mlx_affine.py']:raise ValueError('Oracle exporter source differs')
 binaries=list((R/'.venv/lib').glob('python*/site-packages/mlx/'+fixture['oracle_binary']['name']))
 if len(binaries)!=1 or p.sha(binaries[0])!=fixture['oracle_binary']['sha256']:raise ValueError('Oracle binary identity differs')
 rows=[('export',[sys.executable,'tools/reference/mlx_qwen.py','--export','tests/fixtures/mlx-qwen-v1'])]
 for label,cmd in rows:
  row=p.owned(cmd,O/(label+'.stdout'),O/(label+'.stderr'),env,900);commands.append(row)
  if row['exit_code']!=0 or row['primary_error'] or row['cleanup_errors']:raise RuntimeError('Failed check: '+label)
 if p.sha(binaries[0])!=fixture['oracle_binary']['sha256']:raise ValueError('Oracle binary changed during checks')
except BaseException as e:primary=type(e).__name__+': '+str(e)
finally:
 signal.signal(signal.SIGTERM,previous)
 for n,h in {**pins,**protected}.items():
  try:
   if p.sha(R/n)!=h:endpoints.append('Changed check input: '+n)
  except OSError:endpoints.append('Missing check input: '+n)
 r=dict(format='toklet-native-mlx-qwen-oracle-export-v1',passed=primary is None and not endpoints,source_pins=pins,protected_binary_pins=protected,commands=commands,primary_error=primary,endpoint_errors=endpoints)
 with (O/'checks.json').open('x') as f:json.dump(r,f,indent=2);f.write('\n')
 print(json.dumps(dict(passed=r['passed'],commands=len(commands),primary_error=primary,endpoint_errors=endpoints)));sys.exit(0 if r['passed'] else 1)

